#!/usr/bin/env node
/* eslint-disable no-console */

/**
 * Compute the S3 cache key for the nightly e2e userdata fixtures (QAA-1285).
 *
 * The key is computed identically by the nightly producer workflow and the
 * `restore-e2e-userdata` consumer composite so a day's e2e run can find the
 * bundle generated by the most recent nightly:
 *
 *   e2e-userdata-v<SCHEMA>-<YYYYMMDD>-<scenarioHash>
 *
 * - SCHEMA       : read from `E2E_USERDATA_SCHEMA_VERSION` (single source of
 *                  truth) so a bump automatically invalidates old keys.
 * - YYYYMMDD     : UTC date, optionally overridden by argv[2] (the restore
 *                  ladder probes today then previous days).
 * - scenarioHash : 12-hex-char sha256 of the files that determine the produced
 *                  fixtures' coverage/shape. Editing any of them busts the key,
 *                  so that day live-generates and the next nightly refreshes it.
 *
 * Usage:
 *   node scripts/e2e-userdata-cache-key.mjs            # today (UTC)
 *   node scripts/e2e-userdata-cache-key.mjs 20260607   # a specific UTC day
 */

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const currentDir = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(currentDir, "..");

// Files whose content changes which accounts/addresses get generated or how
// they are serialized. Keep in sync with the generator inputs.
const SCENARIO_FILES = [
  "libs/ledger-live-common/src/e2e/enum/Account.ts",
  "libs/ledger-live-common/src/e2e/userdataFixtureManifest.ts",
  "apps/cli/src/commands/live/liveData.ts",
];

const SCHEMA_SOURCE = "libs/ledger-live-common/src/e2e/userdataFixtureManifest.ts";

function read(relPath) {
  return fs.readFileSync(path.join(repoRoot, relPath), "utf8");
}

function readSchemaVersion() {
  const match = read(SCHEMA_SOURCE).match(/E2E_USERDATA_SCHEMA_VERSION\s*=\s*(\d+)/);
  if (!match) {
    throw new Error(`Could not read E2E_USERDATA_SCHEMA_VERSION from ${SCHEMA_SOURCE}`);
  }
  return match[1];
}

function scenarioHash() {
  const hash = crypto.createHash("sha256");
  for (const file of SCENARIO_FILES) {
    hash.update(read(file));
    hash.update("\0");
  }
  return hash.digest("hex").slice(0, 12);
}

function resolveDate(arg) {
  if (arg) {
    if (!/^\d{8}$/.test(arg)) {
      throw new Error(`Invalid date '${arg}', expected YYYYMMDD`);
    }
    return arg;
  }
  return new Date().toISOString().slice(0, 10).replace(/-/g, "");
}

try {
  const key = `e2e-userdata-v${readSchemaVersion()}-${resolveDate(process.argv[2])}-${scenarioHash()}`;
  process.stdout.write(key);
} catch (error) {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
}
